    this.requireOpen();
    if(positions.length%3||scalars.length!==positions.length/3||indices.length%3||stops.length<8||stops.length%4||
       !positions.every(Number.isFinite)||!scalars.every(Number.isFinite)||!stops.every(Number.isFinite)||
       indices.some(i=>!Number.isInteger(i)||i<0||i>=scalars.length))throw new Error('Invalid scalar mesh buffers');
